vec3 z = (eye - center).normalize();
vec3 x = (up % z).normalize();
vec3 y = (z % x).normalize();

mat4 view;
view[0] = {x.x, y.x, z.x, 0};
view[1] = {x.y, y.y, z.y, 0};
view[2] = {x.z, y.z, z.z, 0};
view[3] = {-(x*eye), -(y*eye), -(z*eye), 1};

return view;

